<?php namespace App\Http\Middleware; use Closure; use Tymon\JWTAuth\Facades\JWTAuth; use Illuminate\Http\Request; class JwtMiddleware {public function handle(Request $r,Closure $next){try{$u=JWTAuth::parseToken()->authenticate();if(!$u)return response()->json(['success'=>false,'message'=>'Unauthenticated','errors'=>[]],401);$r->setUser($u);return $next($r);}catch(\Throwable $e){return response()->json(['success'=>false,'message'=>'Unauthenticated','errors'=>[]],401);}}}
